// Generated by allium:propagate from spec/recipe-ideas.allium (archived_at, ArchiveIdea, RestoreIdea, the
// requires: idea.archived_at = null on EditIdea, ResearchIdea, PickCandidate and UseOwnRecipe, and DeleteIdea,
// KeepIdea, ForgetRealisedIdea and IdeaList for archived ideas). Do not edit by hand: change the spec and propagate.
import { describe, expect, it } from "vitest";
import {
  defaultIdeaConfig,
  recipeIdeaId,
  type IdeaConfig,
  type RecipeDraft,
  type RecipeIdea,
  type RecipeIdeaId,
  type ResearchRequest,
  type Result,
  type Vocabulary,
} from "@weekly-planner/domain";
import type {
  IdeaResearcher,
  InspirationReader,
  RecipeIdeaRepository,
  ResearchRequestLog,
} from "../src/ports/recipe-ideas.js";
import * as useCases from "../src/use-cases/recipe-ideas.js";
import {
  ArchiveIdea,
  DeleteIdea,
  EditIdea,
  KeepIdea,
  ListIdeas,
  NoteIdea,
  PickCandidate,
  ResearchIdea,
  RestoreIdea,
  UseOwnRecipe,
} from "../src/use-cases/recipe-ideas.js";
import { CreateImportedRecipe, type DraftRecipeImport } from "../src/use-cases/recipe-import.js";
import type { RecipeWriter } from "../src/ports/recipe-import.js";
import { AC, FakeClock, ME, SequenceIds } from "./support/in-memory.js";

const MINUTE = 60_000;
const HOUR = 60 * MINUTE;
const WEEK = 7 * 24 * HOUR;

class InMemoryIdeas implements RecipeIdeaRepository {
  readonly byId = new Map<RecipeIdeaId, RecipeIdea>();
  saves = 0;
  async get(id: RecipeIdeaId) {
    return this.byId.get(id) ?? null;
  }
  async save(idea: RecipeIdea) {
    this.saves++;
    this.byId.set(idea.id, idea);
  }
  async remove(id: RecipeIdeaId) {
    this.byId.delete(id);
  }
  async listAll() {
    return [...this.byId.values()];
  }
}

class InMemoryResearchRequests implements ResearchRequestLog {
  readonly all: ResearchRequest[] = [];
  async add(request: ResearchRequest) {
    this.all.push(request);
  }
  async listSince(from: number) {
    return this.all.filter((r) => r.requestedAt >= from);
  }
}

type ResearchQuery = Parameters<IdeaResearcher["research"]>[0];

class FakeInspiration implements InspirationReader {
  readonly read: string[] = [];
  async readInspiration(address: string) {
    this.read.push(address);
    return "Kürbis aus dem Ofen";
  }
}

class FakeResearcher implements IdeaResearcher {
  readonly asked: ResearchQuery[] = [];
  async research(query: ResearchQuery) {
    this.asked.push(query);
    return {
      candidates: [
        {
          title: "Kürbisgnocchi mit Salbei",
          link: "https://example.org/gnocchi",
          summary: "Mit Salbeibutter",
        },
        {
          title: "Ofenkürbis",
          link: "https://example.org/ofen",
          summary: "Schnell",
        },
      ],
    };
  }
}

class FakeDraftImport implements Pick<DraftRecipeImport, "execute"> {
  readonly read: { member: string; address?: string; text?: string }[] = [];
  result: Result<RecipeDraft> = {
    ok: true,
    value: { name: "Kürbisgnocchi" } as RecipeDraft,
  };
  async execute(cmd: { member: RecipeIdea["addedBy"]; address?: string; text?: string }) {
    this.read.push(cmd);
    return this.result;
  }
}

function ideas(config: IdeaConfig = defaultIdeaConfig) {
  const repo = new InMemoryIdeas();
  const requests = new InMemoryResearchRequests();
  const researcher = new FakeResearcher();
  const inspiration = new FakeInspiration();
  const draft = new FakeDraftImport();
  const clock = new FakeClock();
  const ids = new SequenceIds();
  return {
    repo,
    requests,
    researcher,
    inspiration,
    draft,
    clock,
    config,
    note: new NoteIdea({ ideas: repo, clock, ids }),
    edit: new EditIdea({ ideas: repo, clock }),
    list: new ListIdeas({ ideas: repo, clock }, config),
    research: new ResearchIdea({ ideas: repo, requests, researcher, inspiration, clock }, config),
    pick: new PickCandidate({ ideas: repo, clock, draft }),
    own: new UseOwnRecipe({ ideas: repo, clock, draft }),
    keep: new KeepIdea({ ideas: repo, clock }, config),
    remove: new DeleteIdea({ ideas: repo }),
  };
}
type Harness = ReturnType<typeof ideas>;

// Built on use, so that the refusals below run against the existing use cases on their own.
const archiveOf = (h: Harness) => new ArchiveIdea({ ideas: h.repo, clock: h.clock });
const restoreOf = (h: Harness) => new RestoreIdea({ ideas: h.repo, clock: h.clock });

const must = <T>(r: Result<T>): T => {
  if (!r.ok) throw new Error(`rejected: ${r.reason}`);
  return r.value;
};

/** Moves the fake clock forward by whole hours (it counts in hours of a day). */
const advance = (clock: FakeClock, ms: number) => {
  const target = clock.now() + ms;
  const d = new Date(target);
  clock.date = d.toISOString().slice(0, 10) as FakeClock["date"];
  clock.hour = d.getUTCHours();
  expect(clock.now()).toBe(target);
};

/** A researched idea with note and link, an hour old. */
async function aFullIdea(h: Harness): Promise<RecipeIdea> {
  const idea = must(
    await h.note.execute({
      member: ME,
      title: "etwas mit Kürbis",
      note: "Hokkaido",
      inspirationLink: "https://i.org",
    }),
  );
  must(await h.research.execute({ member: ME, idea: idea.id }));
  advance(h.clock, HOUR);
  return (await h.repo.get(idea.id))!;
}

/** Puts the idea aside straight in the store (as ArchiveIdea would), so the refusals do not depend on ArchiveIdea. */
async function putAside(h: Harness, idea: RecipeIdea): Promise<RecipeIdea> {
  const archived: RecipeIdea = { ...idea, archivedAt: h.clock.now() };
  await h.repo.save(archived);
  advance(h.clock, HOUR);
  return archived;
}

describe("the use cases ArchiveIdea and RestoreIdea", () => {
  it("are exported", () => {
    expect(typeof useCases.ArchiveIdea).toBe("function");
    expect(typeof useCases.RestoreIdea).toBe("function");
  });
});

describe("ArchiveIdea", () => {
  it("lets either member put any idea aside: archived now, clock untouched, note, link and candidates kept", async () => {
    const h = ideas();
    const idea = await aFullIdea(h);
    advance(h.clock, 2 * WEEK);
    const archived = must(await archiveOf(h).execute({ member: AC, idea: idea.id }));
    expect(archived).toEqual({ ...idea, archivedAt: h.clock.now() });
    expect(archived.lastTouchedAt).toBe(idea.lastTouchedAt);
    expect(await h.repo.get(idea.id)).toEqual(archived);
  });

  it("refuses an idea that is already archived, and changes nothing", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    expect(await archiveOf(h).execute({ member: ME, idea: archived.id })).toEqual({
      ok: false,
      reason: "already_archived",
    });
    expect(await h.repo.get(archived.id)).toEqual(archived);
  });

  it("says when the idea is gone", async () => {
    const h = ideas();
    expect(await archiveOf(h).execute({ member: ME, idea: recipeIdeaId("gone") })).toEqual({
      ok: false,
      reason: "idea_not_found",
    });
    expect(h.repo.byId.size).toBe(0);
  });
});

describe("RestoreIdea", () => {
  it("brings an archived idea back with its note, link and candidates, its clock started again", async () => {
    const h = ideas();
    const idea = await aFullIdea(h);
    must(await archiveOf(h).execute({ member: ME, idea: idea.id }));
    advance(h.clock, 30 * WEEK);
    const restored = must(await restoreOf(h).execute({ member: AC, idea: idea.id }));
    expect(restored).toEqual({
      ...idea,
      archivedAt: null,
      lastTouchedAt: h.clock.now(),
    });
    expect(await h.repo.get(idea.id)).toEqual(restored);
    // It does not come back stale and straight into cleanup.
    expect(must(await h.list.execute()).find((i) => i.id === idea.id)?.isStale).toBe(false);
  });

  it("refuses an idea that is not archived, and changes nothing", async () => {
    const h = ideas();
    const idea = await aFullIdea(h);
    advance(h.clock, HOUR);
    expect(await restoreOf(h).execute({ member: ME, idea: idea.id })).toEqual({
      ok: false,
      reason: "not_archived",
    });
    expect(await h.repo.get(idea.id)).toEqual(idea);
  });

  it("says when the idea is gone", async () => {
    const h = ideas();
    expect(await restoreOf(h).execute({ member: ME, idea: recipeIdeaId("gone") })).toEqual({
      ok: false,
      reason: "idea_not_found",
    });
  });

  it("makes the idea editable, researchable and pickable again", async () => {
    const h = ideas();
    const idea = await putAside(h, await aFullIdea(h));
    must(await restoreOf(h).execute({ member: ME, idea: idea.id }));
    expect(
      must(
        await h.edit.execute({
          member: AC,
          idea: idea.id,
          title: "Kürbisgnocchi",
        }),
      ).title,
    ).toBe("Kürbisgnocchi");
    must(await h.research.execute({ member: AC, idea: idea.id }));
    expect(await h.pick.execute({ member: AC, idea: idea.id, candidate: 0 })).toEqual(h.draft.result);
  });
});

describe("an archived idea is not worked on", () => {
  it("EditIdea refuses it and changes nothing", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    const saves = h.repo.saves;
    expect(
      await h.edit.execute({
        member: AC,
        idea: archived.id,
        title: "Kürbisgnocchi",
        note: "neu",
      }),
    ).toEqual({
      ok: false,
      reason: "archived",
    });
    expect(await h.repo.get(archived.id)).toEqual(archived);
    expect(h.repo.saves).toBe(saves);
  });

  it("ResearchIdea refuses it without reading the inspiration, asking the model or counting a request", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    const asked = h.researcher.asked.length;
    const read = h.inspiration.read.length;
    const counted = h.requests.all.length;
    expect(await h.research.execute({ member: AC, idea: archived.id })).toEqual({ ok: false, reason: "archived" });
    expect(h.researcher.asked).toHaveLength(asked);
    expect(h.inspiration.read).toHaveLength(read);
    expect(h.requests.all).toHaveLength(counted);
    expect(await h.repo.get(archived.id)).toEqual(archived);
  });

  it("ResearchIdea tells that the idea is archived before looking at the hourly limit", async () => {
    const h = ideas({ ...defaultIdeaConfig, maxResearchPerHour: 1 });
    const archived = await putAside(h, await aFullIdea(h));
    // The one research of aFullIdea was an hour ago; ask once more so the member is at the limit.
    await h.requests.add({ requestedBy: ME, requestedAt: h.clock.now() });
    expect(await h.research.execute({ member: ME, idea: archived.id })).toEqual({ ok: false, reason: "archived" });
    expect(h.researcher.asked).toHaveLength(1);
  });

  it("PickCandidate refuses it: no draft is started and the idea's clock stays", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    expect(await h.pick.execute({ member: AC, idea: archived.id, candidate: 0 })).toEqual({
      ok: false,
      reason: "archived",
    });
    expect(h.draft.read).toEqual([]);
    expect(await h.repo.get(archived.id)).toEqual(archived);
  });

  it("UseOwnRecipe refuses it, for a link and for text: no draft is started and the idea's clock stays", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    const saves = h.repo.saves;
    for (const source of [{ address: "https://example.org/mine" }, { text: "Kürbis schälen ..." }]) {
      expect(await h.own.execute({ member: AC, idea: archived.id, ...source })).toEqual({
        ok: false,
        reason: "archived",
      });
    }
    expect(h.draft.read).toEqual([]);
    expect(await h.repo.get(archived.id)).toEqual(archived);
    expect(h.repo.saves).toBe(saves);
  });

  it("KeepIdea refuses it however old it is: an archived idea is never stale", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    advance(h.clock, 52 * WEEK);
    expect(await h.keep.execute({ member: ME, idea: archived.id })).toEqual({
      ok: false,
      reason: "not_stale",
    });
    expect(await h.repo.get(archived.id)).toEqual(archived);
  });
});

describe("DeleteIdea on an archived idea", () => {
  it("drops it for good, its candidates with it", async () => {
    const h = ideas();
    const archived = await putAside(h, await aFullIdea(h));
    expect((await h.remove.execute({ member: AC, idea: archived.id })).ok).toBe(true);
    expect(await h.repo.get(archived.id)).toBeNull();
    expect(must(await h.list.execute())).toEqual([]);
  });

  it("drops one archived through ArchiveIdea just the same", async () => {
    const h = ideas();
    const idea = await aFullIdea(h);
    must(await archiveOf(h).execute({ member: ME, idea: idea.id }));
    expect((await h.remove.execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect(await h.repo.get(idea.id)).toBeNull();
  });
});

describe("ListIdeas (surface IdeaList) with archived ideas", () => {
  it("still shows an archived idea with when it was archived, never stale, and keeps it however old", async () => {
    const h = ideas();
    const idea = await aFullIdea(h);
    const archivedAt = h.clock.now();
    await putAside(h, idea);
    const fresh = must(await h.note.execute({ member: AC, title: "neu" }));
    advance(h.clock, 52 * WEEK);
    const listed = must(await h.list.execute());
    expect(listed).toHaveLength(2);
    const byId = new Map(listed.map((i) => [i.id, i]));
    expect(byId.get(idea.id)).toMatchObject({
      note: "Hokkaido",
      inspirationLink: "https://i.org",
      archivedAt,
      isStale: false,
      candidates: idea.candidates,
    });
    expect(byId.get(fresh.id)).toMatchObject({
      archivedAt: null,
      isStale: true,
    });
    expect(await h.repo.get(idea.id)).not.toBeNull();
  });

  it("offers archive only for an idea in the list and restore only for an archived one", async () => {
    const h = ideas();
    const idea = must(await h.note.execute({ member: ME, title: "Kürbis" }));
    expect((await restoreOf(h).execute({ member: ME, idea: idea.id })).ok).toBe(false);
    expect((await archiveOf(h).execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect((await archiveOf(h).execute({ member: ME, idea: idea.id })).ok).toBe(false);
    expect((await restoreOf(h).execute({ member: ME, idea: idea.id })).ok).toBe(true);
    expect((await h.repo.get(idea.id))?.archivedAt).toBeNull();
  });
});

describe("ForgetRealisedIdea for an idea archived meanwhile", () => {
  it("lets the idea go once its recipe is created, archived or not", async () => {
    const h = ideas();
    const vocabulary: Vocabulary = { items: ["Kürbis"], tags: [] };
    const created: RecipeDraft[] = [];
    const writer: RecipeWriter = {
      vocabulary: async () => vocabulary,
      create: async (draft) => {
        created.push(draft);
        return { recipeId: 7, photoAttached: false };
      },
    };
    const create = new CreateImportedRecipe({ writer, ideas: h.repo });
    const archived = await putAside(h, await aFullIdea(h));
    const r = await create.execute({
      member: AC,
      idea: archived.id,
      draft: {
        name: "Kürbisgnocchi",
        steps: ["Kochen."],
        ingredients: [{ name: "Kürbis", amount: "500 g" }],
        mealType: "main",
        base: "other",
        diet: "vegetarian",
        tags: [],
        source: "https://example.org/gnocchi",
      },
    });
    expect(r.ok && r.value.recipeId).toBe(7);
    expect(created).toHaveLength(1);
    expect(await h.repo.get(archived.id)).toBeNull();
  });
});
